const text = $input.first().json.message.text;
const chatId = $input.first().json.message.chat.id;
const courseName = text.replace(/^COURSE:\s*/i, '').trim();

const workflowStaticData = $getWorkflowStaticData('global');
workflowStaticData[`course_${chatId}`] = courseName;

return [{ json: { chat_id: chatId, course_name: courseName } }];

const message = $input.first().json.message;
const photos = message.photo;
const largest = photos[photos.length - 1];
const chatId = message.chat.id;

const workflowStaticData = $getWorkflowStaticData('global');
const courseName = workflowStaticData[`course_${chatId}`] || 'General';

return [{
  json: {
    file_id: largest.file_id,
    chat_id: chatId,
    course_name: courseName
  }
}];

const result = $input.first().json.result;
const filePath = result.file_path;

const chatId = $('Extract Photo Info').first().json.chat_id;
const courseName = $('Extract Photo Info').first().json.course_name;

const credentials = await this.getCredentials('telegramApi');
const token = credentials.accessToken;

return [{
  json: {
    download_url: `https://api.telegram.org/file/bot${token}/${filePath}`,
    chat_id: chatId,
    course_name: courseName
  }
}];

const item = $input.first();
const chatId = $('Build Download URL').first().json.chat_id;
const courseName = $('Build Download URL').first().json.course_name;
const binaryData = item.binary?.photoData;

if (!binaryData) throw new Error('Photo download failed — no binary data.');

const base64 = binaryData.data;
const mimeType = binaryData.mimeType || 'image/jpeg';

return [{
  json: {
    chat_id: chatId,
    course_name: courseName,
    base64_image: base64,
    mime_type: mimeType
  }
}];

const course = ($input.first().json.course_name || '').toLowerCase();
const chatId = $input.first().json.chat_id;
const base64 = $input.first().json.base64_image;
const mimeType = $input.first().json.mime_type;

let systemPrompt = '';

if (/math|calculus|algebra|statistics|maths|trigonometry/.test(course)) {
  systemPrompt = `You are a mathematics tutor for a Nigerian federal university computer engineering student. The student has photographed an assignment question. Read the question from the image carefully.

Produce your response in this exact format:

## QUESTION (as I understand it)
Restate the question in your own words to confirm you read it correctly.

## FULL WORKED SOLUTION
Solve the problem completely. Show every single step. Explain what you are doing at each step and why. Do not skip steps.

## KEY CONCEPTS USED
List the mathematical concepts, theorems, or formulas applied.

## HOW TO WRITE THIS IN YOUR ANSWER BOOKLET
Give a clean, condensed version of the solution that the student can reproduce by hand in an exam. Use clear numbered steps. Estimated time to write: X minutes.`;
} else if (/digital|electronics|logic|circuit|signals|electrical|electromagn/.test(course)) {
  systemPrompt = `You are a digital electronics and computer engineering tutor for a Nigerian federal university student. The student has photographed an assignment question.

Produce your response in this exact format:

## QUESTION (as I understand it)
Restate the question clearly.

## FULL WORKED SOLUTION
Solve completely. Truth tables: draw in ASCII format. K-maps: show groupings in text. Circuit descriptions: describe clearly as component list. Boolean expressions: show all simplification steps. Timing diagrams: represent as ASCII waveforms.

## KEY CONCEPTS USED
State the relevant theorems, laws, or principles (e.g. De Morgan's theorem, Karnaugh map rules, etc.)

## HOW TO WRITE THIS IN YOUR ANSWER BOOKLET
Clean condensed version for hand-reproduction. Estimated time: X minutes.`;
} else if (/programming|software|python|java|c\+\+|algorithm|data struct|compiler|coding/.test(course)) {
  systemPrompt = `You are a programming and software engineering tutor for a Nigerian federal university computer engineering student.

Produce your response in this exact format:

## QUESTION (as I understand it)
Restate the question clearly.

## FULL SOLUTION
If code: write complete working code with comments explaining every line. If conceptual: give a thorough explanation with examples.

## CODE WALKTHROUGH (if applicable)
Explain the code line by line in plain English.

## HOW TO WRITE THIS IN YOUR ANSWER BOOKLET
Clean version for hand-reproduction. For code, give a simplified but complete handwritten-friendly version.`;
} else {
  systemPrompt = `You are an academic tutor for a Nigerian federal university computer engineering student. The student has photographed an assignment question.

Produce your response in this exact format:

## QUESTION (as I understand it)
Restate the question clearly.

## FULL ANSWER
Provide a thorough, well-structured answer appropriate for an undergraduate university assignment. Use clear paragraphs. Include all relevant theory, examples, and explanations. The answer should be at a level that would score full marks.

## KEY POINTS TO REMEMBER
Bullet list of the most important things in this answer.

## HOW TO WRITE THIS IN YOUR ANSWER BOOKLET
A clean, condensed version the student can write by hand. Approximately 300-500 words depending on the question.`;
}

return [{
  json: {
    chat_id: chatId,
    course_name: $input.first().json.course_name,
    base64_image: base64,
    mime_type: mimeType,
    system_prompt: systemPrompt
  }
}];

const response = $input.first().json;
const answerText = response.content[0].text;
const chatId = $('Select System Prompt Based on Course').first().json.chat_id;
const courseName = $('Select System Prompt Based on Course').first().json.course_name;

const chunkSize = 4000;
const chunks = [];
for (let i = 0; i < answerText.length; i += chunkSize) {
  chunks.push(answerText.slice(i, i + chunkSize));
}

return chunks.map((chunk, i) => ({
  json: {
    text: chunk,
    chat_id: chatId,
    course_name: courseName,
    chunk_index: i,
    total_chunks: chunks.length,
    full_answer: i === 0 ? answerText : null
  }
}));
